	@Test
	void closeAtOverflowBoundaryDoesNotOpenFallback() {
		withRowLimit(1, () -> {
			AtomicReference<CloseableIteration<BindingSet>> outer = new AtomicReference<>();
			AtomicInteger leftOpens = new AtomicInteger();
			AtomicInteger rightOpens = new AtomicInteger();
			QueryEvaluationStep step = step(bindings -> {
				leftOpens.incrementAndGet();
				return new TrackingIteration(List.of(row()));
			}, bindings -> {
				rightOpens.incrementAndGet();
				return new TrackingIteration(List.of(row(), row())) {
					@Override
					protected void handleClose() {
						super.handleClose();
						outer.get().close();
					}
				};
			}, true);
			try (var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
				outer.set(iteration);
				assertFalse(iteration.hasNext());
				assertEquals(1, leftOpens.get());
				assertEquals(1, rightOpens.get());
			}
		});
	}

	@Test
	void closeDuringFallbackRightOpenClosesReturnedScan() {
		withRowLimit(1, () -> {
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			TrackingIteration delayed = new TrackingIteration(List.of(row()));
			AtomicInteger rightOpens = new AtomicInteger();
			QueryEvaluationStep step = step(bindings -> new TrackingIteration(List.of(row())), bindings -> {
				if (rightOpens.incrementAndGet() == 1) {
					return new TrackingIteration(List.of(row(), row()));
				}
				entered.countDown();
				await(release);
				return delayed;
			}, true);
			try (var executor = Executors.newSingleThreadExecutor();
					var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
				var worker = executor.submit(iteration::hasNext);
				try {
					assertTrue(entered.await(5, TimeUnit.SECONDS));
					iteration.close();
				} finally {
					release.countDown();
				}
				assertFalse(worker.get(5, TimeUnit.SECONDS));
			} catch (Exception e) {
				throw new AssertionError(e);
			}
			assertEquals(1, delayed.closes.get());
			assertEquals(0, delayed.reads.get());
			assertEquals(2, rightOpens.get());
		});
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 10 })
	void completedHashOrOverflowFallbackPreservesBagAndClosesInputs(int rowLimit) {
		withRowLimit(rowLimit, () -> {
			List<TrackingIteration> inputs = new ArrayList<>();
			AtomicInteger rightOpens = new AtomicInteger();
			QueryEvaluationStep step = step(bindings -> {
				TrackingIteration input = new TrackingIteration(List.of(row(), row()));
				inputs.add(input);
				return input;
			}, bindings -> {
				rightOpens.incrementAndGet();
				TrackingIteration input = new TrackingIteration(List.of(row(), row(), row()));
				inputs.add(input);
				return input;
			}, true);
			try (var iteration = step.evaluate(EmptyBindingSet.getInstance())) {
				List<BindingSet> results = new ArrayList<>();
				iteration.forEachRemaining(results::add);
				assertEquals(6, results.size());
			}
			assertEquals(rowLimit == 1 ? 3 : 1, rightOpens.get());
			inputs.forEach(input -> assertEquals(1, input.closes.get()));
		});
	}

	@Test
	void firstReadFailureClosesInputAndRetainsCloseFailure() {
		IllegalStateException readFailure = new IllegalStateException("left read failed");
		IllegalArgumentException closeFailure = new IllegalArgumentException("left close failed");
		TrackingIteration left = new TrackingIteration(List.of(row())) {
			@Override
			public boolean hasNext() {
				throw readFailure;
			}

			@Override
			protected void handleClose() {
				super.handleClose();
				throw closeFailure;
			}
		};
		try (var iteration = step(bindings -> left, bindings -> {
			throw new AssertionError("No right open after a left input failure");
		}, true).evaluate(EmptyBindingSet.getInstance())) {
			assertSame(readFailure, assertThrows(IllegalStateException.class, iteration::hasNext));
			assertEquals(List.of(closeFailure), List.of(readFailure.getSuppressed()));
			assertEquals(1, left.closes.get());
		}
	}

