	private static void withRowLimit(int limit, Runnable action) {
		String property = LeftJoinQueryEvaluationStep.MAX_MATERIALIZED_RIGHT_ROWS_PROPERTY;
		String previous = System.setProperty(property, Integer.toString(limit));
		try {
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	private static QueryEvaluationStep step(QueryEvaluationStep left, QueryEvaluationStep right, boolean union) {
		StatementPattern leftArg = pattern("left");
		TupleExpr rightArg = union ? new Union(pattern("detail"), pattern("detail")) : pattern("detail");
		LeftJoin optional = new LeftJoin(leftArg, rightArg);
		if (!union) {
			optional.setStringMetricPlanned("optimizer.joinAlgorithmHint", "hash");
		}
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		doReturn(left).when(strategy).precompile(eq((TupleExpr) leftArg), eq(context));
		doReturn(right).when(strategy).precompile(eq(rightArg), eq(context));
		return LeftJoinQueryEvaluationStep.supply(strategy, optional, context);
	}

	private static StatementPattern pattern(String objectName) {
		return new StatementPattern(Var.of("root"),
				Var.of("predicate", SimpleValueFactory.getInstance().createIRI("urn:predicate"), true, true),
				Var.of(objectName));
	}

	private static BindingSet row() {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("root", SimpleValueFactory.getInstance().createIRI("urn:root"));
		return row;
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(10, TimeUnit.SECONDS), "Fixture must be released by cancellation or cleanup");
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static class TrackingIteration extends CloseableIteratorIteration<BindingSet> {
		private final AtomicInteger closes = new AtomicInteger();
		private final AtomicInteger reads = new AtomicInteger();

		private TrackingIteration(List<BindingSet> rows) {
			super(rows.iterator());
		}

		@Override
		public boolean hasNext() {
			reads.incrementAndGet();
			return super.hasNext();
		}

		@Override
		protected void handleClose() {
			closes.incrementAndGet();
		}
	}
